//! Smart routing provider that routes requests to cheap or primary models based on task complexity.//!//! Uses a 13-dimension complexity scorer (from PR #208 by @onlyamicrowave) to analyze prompts//! across reasoning, code, multi-step, domain-specific, creativity, precision, safety, and other//! dimensions. Pattern overrides provide fast-path routing for obvious cases (greetings → cheap,//! security audits → primary).//!//! This is a decorator that wraps two `LlmProvider`s and implements `LlmProvider` itself,//! following the same pattern as `RetryProvider`, `CachedProvider`, and `CircuitBreakerProvider`.//!//! # Complexity Tiers//!//! The scorer produces a 0-100 score mapped to four tiers://! - **Flash** (0-15): Greetings, quick lookups → cheap model//! - **Standard** (16-40): Writing, comparisons → cheap model//! - **Pro** (41-65): Multi-step analysis, code review → cheap with cascade, or primary//! - **Frontier** (66+): Security audits, critical decisions → primary modeluse std::collections::HashMap;use std::sync::Arc;use std::sync::atomic::{AtomicU64, Ordering};use async_trait::async_trait;use regex::Regex;use rust_decimal::Decimal;use crate::llm::error::LlmError;use crate::llm::provider::{    CompletionRequest, CompletionResponse, LlmProvider, ModelMetadata, Role, ToolCompletionRequest,    ToolCompletionResponse,};// ---------------------------------------------------------------------------// Complexity tiers & scoring// ---------------------------------------------------------------------------/// Complexity tier produced by the 13-dimension scorer.#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]pub enum Tier {    /// Simple requests: greetings, quick lookups (score 0-15).    Flash,    /// Standard tasks: writing, comparisons (score 16-40).    Standard,    /// Complex work: multi-step analysis, code review (score 41-65).    Pro,    /// Critical tasks: security audits, high-stakes decisions (score 66+).    Frontier,}impl Tier {    /// Convert a complexity score to a tier.    pub fn from_score(score: u32) -> Self {        match score {            0..=15 => Tier::Flash,            16..=40 => Tier::Standard,            41..=65 => Tier::Pro,            _ => Tier::Frontier,        }    }    /// Get a representative score for this tier (used when score is not computed).    pub fn to_score(self) -> u32 {        match self {            Tier::Flash => 8,            Tier::Standard => 28,            Tier::Pro => 52,            Tier::Frontier => 80,        }    }    /// Tier name as string.    pub fn as_str(&self) -> &'static str {        match self {            Tier::Flash => "flash",            Tier::Standard => "standard",            Tier::Pro => "pro",            Tier::Frontier => "frontier",        }    }}impl std::fmt::Display for Tier {    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {        write!(f, "{}", self.as_str())    }}/// Weights for each of the 13 scoring dimensions.#[derive(Debug, Clone)]pub struct ScorerWeights {    pub reasoning_words: f32,    pub token_estimate: f32,    pub code_indicators: f32,    pub multi_step: f32,    pub domain_specific: f32,    pub ambiguity: f32,    pub creativity: f32,    pub precision: f32,    pub context_dependency: f32,    pub tool_likelihood: f32,    pub safety_sensitivity: f32,    pub question_complexity: f32,    pub sentence_complexity: f32,}impl Default for ScorerWeights {    fn default() -> Self {        Self {            reasoning_words: 0.14,            token_estimate: 0.12,            code_indicators: 0.10,            multi_step: 0.10,            domain_specific: 0.10,            ambiguity: 0.05,            creativity: 0.07,            precision: 0.06,            context_dependency: 0.05,            tool_likelihood: 0.05,            safety_sensitivity: 0.04,            question_complexity: 0.07,            sentence_complexity: 0.05,        }    }}/// Default domain-specific keywords for complexity scoring.pub const DEFAULT_DOMAIN_KEYWORDS: &[&str] = &[    // Infrastructure    "kubernetes",    "k8s",    "docker",    "terraform",    "nginx",    "apache",    "linux",    "unix",    "bash",    "shell",    // Languages & frameworks    "solidity",    "rust",    "typescript",    "react",    "nextjs",    "vue",    "angular",    "svelte",    // Databases    "postgresql",    "postgres",    "mysql",    "mongodb",    "redis",    // APIs & protocols    "graphql",    "grpc",    "protobuf",    "websocket",    "oauth",    "jwt",    "cors",    "csrf",    "xss",    "sql.?injection",    "api",    "rest",    "http",    "https",    "tcp",    "udp",    "dns",    "cdn",    // Cloud & deployment    "aws",    "gcp",    "azure",    "vercel",    "netlify",    "cloudflare",    "ci/cd",    "devops",    // Version control    "git",    "github",    "gitlab",    // Web3 general    "blockchain",    "web3",    "defi",    "nft",    "smart.?contract",    // Ethereum    "ethereum",    "evm",    "anchor",    // NEAR ecosystem    "near",    "near.?sdk",    "near.?api",    "testnet",    "mainnet",    "meteor",    "ledger",    "cold.?wallet",    "rpc",    "indexer",    "relayer",    "cross.?chain",    "intents",    // Fogo/SVM    "fogo",    "svm",    "firedancer",    "paymaster",    "gasless",    "sessions.?sdk",    // Rust/NEAR tooling    "cargo.?near",    "workspaces",    "sandbox",    // Project-specific    "lobo",    "trezu",    "multisig",    "treasury",    "openclaw",    "ironclaw",];/// Configuration for the complexity scorer.#[derive(Debug, Clone, Default)]pub struct ScorerConfig {    /// Weights for each scoring dimension.    pub weights: ScorerWeights,    /// Custom domain-specific keywords (overrides defaults if provided).    /// Each entry is a word or regex pattern fragment.    pub domain_keywords: Option<Vec<String>>,}/// Build a domain regex from a keyword list, with fallback on invalid patterns.////// An empty keyword list falls back to the default keywords so scoring/// doesn't break when `domain_keywords: Some(vec![])` is configured.fn build_domain_regex(keywords: &[&str]) -> Regex {    if keywords.is_empty() {        return RE_DOMAIN_DEFAULT.clone();    }    let pattern = format!(r"(?i)\b({})\b", keywords.join("|"));    Regex::new(&pattern).unwrap_or_else(|e| {        tracing::warn!(error = %e, "Invalid domain keywords pattern, using minimal fallback");        Regex::new(r"(?i)\b(api|code|deploy)\b").expect("fallback regex is valid") // safety: hardcoded literal    })}/// Breakdown of complexity score by dimension.#[derive(Debug, Clone)]pub struct ScoreBreakdown {    /// Total complexity score (0-100).    pub total: u32,    /// Computed tier.    pub tier: Tier,    /// Per-dimension scores (0-100 each).    pub components: HashMap<String, u32>,    /// Human-readable hints about why this score.    pub hints: Vec<String>,}// ---------------------------------------------------------------------------// Static regex patterns (compiled once via LazyLock)// ---------------------------------------------------------------------------use std::sync::LazyLock;static RE_REASONING: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(why|how|explain|analyze|analyse|compare|contrast|evaluate|assess|reason|think|consider|implications?|consequences?|trade-?offs?|pros?\s*(and|&)\s*cons?|advantages?|disadvantages?|benefits?|drawbacks?|differs?|difference|versus|vs\.?|better|worse|optimal|best|worst)\b"    ).expect("RE_REASONING is a valid regex") // safety: hardcoded literal});static RE_MULTI_STEP: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(first|then|next|after|before|finally|step|steps|phase|stages?|process|workflow|sequence|procedure|pipeline|chain|series|order|followed by)\b"    ).expect("RE_MULTI_STEP is a valid regex") // safety: hardcoded literal});static RE_CREATIVITY: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(write|create|generate|compose|design|imagine|brainstorm|ideate|draft|invent|story|poem|essay|article|blog|content|narrative|script|summarize|summarise|rewrite|paraphrase|translate|adapt|tweet|post|thread|outline|structure|format|style|tone|voice)\b"    ).expect("RE_CREATIVITY is a valid regex") // safety: hardcoded literal});static RE_PRECISION: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(\d{4}|\d+\.\d+|exactly|precisely|specific|accurate|correct|verify|confirm|date|time|number|calculate|compute|measure|count)\b"    ).expect("RE_PRECISION is a valid regex") // safety: hardcoded literal});static RE_CODE: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)(`{1,3}|```|function|const|let|var|import|export|class|def |async|await|=>|\.ts|\.js|\.py|\.rs|\.go|\.sol|\(\)|\[\]|\{\}|<[A-Z][a-z]+>|useState|useEffect|npm|yarn|pnpm|cargo|pip|implement|rebase|merge|commit|branch|PR|pull.?request|columns?|migrations?|module|refactor|debug|fix|bug|error|schema|database|query)"    ).expect("RE_CODE is a valid regex") // safety: hardcoded literal});static RE_TOOL: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(file|read|write|search|fetch|run|execute|check|look up|find|open|save|send|post|get|download|upload|install|deploy|build|compile|test|add|update|remove|delete|modify|change|edit|create|resolve|push|pull|clone)\b"    ).expect("RE_TOOL is a valid regex") // safety: hardcoded literal});static RE_SAFETY: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(password|secret|private|confidential|medical|legal|financial|personal|sensitive|ssn|credit.?card|auth|token|key|encrypt|decrypt|hash|vulnerability|exploit|attack|breach)\b"    ).expect("RE_SAFETY is a valid regex") // safety: hardcoded literal});static RE_CONTEXT: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(previous|earlier|above|before|last|that|those|it|they|we discussed|you said|mentioned|remember|recall|as I said|like I mentioned)\b"    ).expect("RE_CONTEXT is a valid regex") // safety: hardcoded literal});static RE_VAGUE: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(r"(?i)\b(it|this|that|something|stuff|thing|things)\b")        .expect("RE_VAGUE is a valid regex") // safety: hardcoded literal});static RE_OPEN_ENDED: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(r"(?i)\b(why|how|what if|explain|describe|elaborate|discuss)\b")        .expect("RE_OPEN_ENDED is a valid regex") // safety: hardcoded literal});static RE_CONJUNCTIONS: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(        r"(?i)\b(and|but|or|however|therefore|because|although|while|whereas|moreover|furthermore)\b",    )    .expect("RE_CONJUNCTIONS is a valid regex") // safety: hardcoded literal});static RE_TIER_HINT: LazyLock<Regex> = LazyLock::new(|| {    Regex::new(r"(?i)\[tier:(flash|standard|pro|frontier)\]")        .expect("RE_TIER_HINT is a valid regex") // safety: hardcoded literal});/// Default domain regex, compiled once from `DEFAULT_DOMAIN_KEYWORDS`.static RE_DOMAIN_DEFAULT: LazyLock<Regex> =    LazyLock::new(|| build_domain_regex(DEFAULT_DOMAIN_KEYWORDS));// ---------------------------------------------------------------------------// Pattern overrides (fast-path before scoring)// ---------------------------------------------------------------------------/// A compiled pattern override entry.struct PatternOverride {    regex: Regex,    tier: Tier,}/// Default pattern overrides, compiled once.static DEFAULT_OVERRIDES: LazyLock<Vec<PatternOverride>> = LazyLock::new(|| {    vec![        // Flash tier: greetings and acknowledgments        PatternOverride {            regex: Regex::new(                r"(?i)^(hi|hello|hey|thanks|ok|sure|yes|no|yep|nope|cool|nice|great|got it)$",            )            .expect("greeting pattern is valid"), // safety: hardcoded literal            tier: Tier::Flash,        },        // Flash tier: quick lookups (end-anchored to avoid matching complex questions        // like "What time complexity is merge sort?")        PatternOverride {            regex: Regex::new(                r"(?i)^what(?:'s|\s+is)?\s+(?:the\s+)?(time|date|day|weather)\b(?:\s+(?:is\s+it|today|now|in\s+\S+))?[?.!]*$",            )            .expect("lookup pattern is valid"), // safety: hardcoded literal            tier: Tier::Flash,        },        // Frontier tier: security audits        PatternOverride {            regex: Regex::new(r"(?i)security.*(audit|review|scan)")                .expect("security audit pattern is valid"), // safety: hardcoded literal            tier: Tier::Frontier,        },        PatternOverride {            regex: Regex::new(r"(?i)vulnerabilit(y|ies).*(review|scan|check|audit)")                .expect("vulnerability pattern is valid"), // safety: hardcoded literal            tier: Tier::Frontier,        },        // Pro tier: production deployments        PatternOverride {            regex: Regex::new(r"(?i)deploy.*(mainnet|production)")                .expect("deploy pattern is valid"), // safety: hardcoded literal            tier: Tier::Pro,        },        PatternOverride {            regex: Regex::new(r"(?i)production.*(deploy|release|push)")                .expect("production pattern is valid"), // safety: hardcoded literal            tier: Tier::Pro,        },    ]});// ---------------------------------------------------------------------------// Scoring functions// ---------------------------------------------------------------------------/// Count regex matches in text.fn count_matches(re: &Regex, text: &str) -> usize {    re.find_iter(text).count()}/// Score a prompt's complexity across 13 dimensions.////// Returns a `ScoreBreakdown` with a total score (0-100) and per-dimension breakdown.pub fn score_complexity(prompt: &str) -> ScoreBreakdown {    score_complexity_with_config(prompt, &ScorerConfig::default())}/// Score with custom configuration (weights + domain keywords).////// If you will call this repeatedly with the same config, prefer/// [`score_complexity_with_regex`] and pre-build the domain regex once.pub fn score_complexity_with_config(prompt: &str, config: &ScorerConfig) -> ScoreBreakdown {    let domain_regex = match &config.domain_keywords {        Some(custom) => {            let refs: Vec<&str> = custom.iter().map(|s| s.as_str()).collect();            build_domain_regex(&refs)        }        None => RE_DOMAIN_DEFAULT.clone(),    };    score_complexity_internal(prompt, &config.weights, &domain_regex)}/// Score with a pre-compiled domain regex (avoids rebuilding per call).